signal_cue_instantly.param:
table[$pipe = 'x4_agent',
                     $msg  = 'state money=%s time=%s ship=%s sector=%s zone=%s x=%s y=%s z=%s speed=%s order=%s'.[
                       player.money, player.age, @player.occupiedship.idcode,
                       @player.occupiedship.sector.macro.id, @player.occupiedship.zone.macro.id,
                       @player.occupiedship.position.x, @player.occupiedship.position.y,
                       @player.occupiedship.position.z, @player.occupiedship.speed,
                       '%s/%s/%s/%s'.[@player.occupiedship.order.id, @player.occupiedship.orders.count,
                                      @player.occupiedship.orders.{1}.id, @player.occupiedship.order.script]],
                     $cue  = Write_Callback]
